-- =====================================================================
-- DỮ LIỆU BÁN VÉ MẪU (TÙY CHỌN) để trang Dashboard của admin có số liệu để xem
-- Chạy SAU schema.sql và seed.sql. Có thể chạy lại nhiều lần (tự xóa dữ liệu mẫu cũ trước).
-- Tạo 48 đơn có mã bắt đầu bằng DEMO: 36 đã thanh toán, 6 đã hủy, 6 hết hạn, rải trong 75 ngày qua.
-- Chỉ dùng suất chiếu 1-8 (các script test dùng suất 9, 10 nên không bị ảnh hưởng).
-- XÓA dữ liệu mẫu bất cứ lúc nào:   DELETE FROM bookings WHERE booking_code LIKE 'DEMO%';
-- =====================================================================
USE movie_booking;
SET NAMES utf8mb4;

DELETE FROM bookings WHERE booking_code LIKE 'DEMO%';


-- Tiền của đơn = tổng giá các ghế
UPDATE bookings b SET
  b.subtotal = (SELECT COALESCE(SUM(bs.price), 0) FROM booking_seats bs WHERE bs.booking_id = b.id),
  b.total_amount = (SELECT COALESCE(SUM(bs.price), 0) FROM booking_seats bs WHERE bs.booking_id = b.id)
WHERE b.booking_code LIKE 'DEMO%';

-- Thanh toán thành công cho đơn paid, đã hoàn tiền cho đơn bị hủy
SELECT b.id, 'mock', b.total_amount, 'success', CONCAT('DEMO-', b.booking_code), b.created_at
FROM bookings b WHERE b.booking_code LIKE 'DEMO%' AND b.status = 'paid';

SELECT b.id, 'mock', b.total_amount, 'refunded', CONCAT('DEMO-', b.booking_code), b.created_at
FROM bookings b WHERE b.booking_code LIKE 'DEMO%' AND b.status = 'cancelled';

